import{_ as t,o as h,c as i,a2 as o}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Sun (Mặt Trời)","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/sun.md","filePath":"astro/planets/sun.md"}'),a={name:"astro/planets/sun.md"};function g(c,n,u,r,s,l){return h(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="sun-mat-troi" tabindex="-1">Sun (Mặt Trời) <a class="header-anchor" href="#sun-mat-troi" aria-label="Permalink to &quot;Sun (Mặt Trời)&quot;">​</a></h1><blockquote><p>Quy ước: <strong>[Sách]</strong> = nội dung có trong các trang bạn chụp. <strong>[Bổ sung]</strong> = kiến thức traditional astrology nói chung, mình thêm vào để nối với phần đã học. Phần [Bổ sung] nên đối chiếu lại với các chương sau của sách (đặc biệt các con số).</p></blockquote><hr><h2 id="_1-vi-tri-cua-sun-trong-he-thong" tabindex="-1">1. Vị trí của Sun trong hệ thống <a class="header-anchor" href="#_1-vi-tri-cua-sun-trong-he-thong" aria-label="Permalink to &quot;1. Vị trí của Sun trong hệ thống&quot;">​</a></h2><h3 id="nhom-two-lights-sach" tabindex="-1">Nhóm Two Lights [Sách] <a class="header-anchor" href="#nhom-two-lights-sach" aria-label="Permalink to &quot;Nhóm Two Lights [Sách]&quot;">​</a></h3><ul><li>Sun + Moon = &quot;Celestial God and Goddess&quot; → hiện xuống đất thành <strong>King và Queen</strong> → rồi thành <strong>cha và mẹ</strong></li><li>Sun chiếu sáng ban ngày, điều chỉnh <strong>các mùa trong năm</strong></li><li>5 hành tinh còn lại giống các <strong>bộ trưởng</strong> phục vụ dưới quyền vua/hoàng hậu</li><li>Paulus: hai ánh sáng &quot;cai quản mọi thứ&quot;, có quyền tối cao</li></ul><p><strong>Hiểu đơn giản:</strong> khi xem lá số, Sun và Moon luôn được xét <strong>trước</strong> 5 hành tinh còn lại. Ví dụ: một người có Mars rất mạnh nhưng Sun yếu nặng thì &quot;vua&quot; đang yếu, các &quot;bộ trưởng&quot; khó làm việc hiệu quả.</p><h3 id="sun-la-trung-tam-cua-đanh-gia-condition-bo-sung-noi-voi-bai-đa-hoc" tabindex="-1">Sun là trung tâm của đánh giá condition [Bổ sung, nối với bài đã học] <a class="header-anchor" href="#sun-la-trung-tam-cua-đanh-gia-condition-bo-sung-noi-voi-bai-đa-hoc" aria-label="Permalink to &quot;Sun là trung tâm của đánh giá condition [Bổ sung, nối với bài đã học]&quot;">​</a></h3><ul><li>Cột &quot;solar phase&quot; trong bảng 3 tầng vũ trụ: <strong>mọi hành tinh khác đều được đánh giá dựa trên khoảng cách tới Sun</strong> (combust, under the beams, oriental/occidental, tốc độ, nhìn thấy hay không)</li><li>Nên Sun vừa là một hành tinh cần đánh giá, vừa là <strong>thước đo</strong> để đánh giá các hành tinh khác</li><li>Sun <strong>không bao giờ retrograde</strong> (luôn đi thuận), nên Sun không có yếu tố &quot;nghịch hành&quot; như 5 hành tinh kia</li></ul><hr><h2 id="_2-ban-chat-va-y-nghia-sach" tabindex="-1">2. Bản chất và ý nghĩa [Sách] <a class="header-anchor" href="#_2-ban-chat-va-y-nghia-sach" aria-label="Permalink to &quot;2. Bản chất và ý nghĩa [Sách]&quot;">​</a></h2><ul><li>&quot;Lửa của tự nhiên&quot;: ánh sáng trí tuệ, cơ quan nhận thức tinh thần, hơi thở sự sống và chuyển động của nó</li><li>Đại diện <strong>linh hồn (soul)</strong>, phần thần thánh trong tâm trí con người</li><li>Tính chất: <strong>nóng, hơi khô</strong></li></ul><table tabindex="0"><thead><tr><th>Nhóm</th><th>Nội dung</th></tr></thead><tbody><tr><td>Con người</td><td>Người cha, người cai trị, người quý tộc, người có danh tiếng</td></tr><tr><td>Chủ đề</td><td>Danh tiếng công khai, vinh dự</td></tr><tr><td>Cơ thể</td><td>Đầu, mắt phải, tim</td></tr><tr><td>Vật chất</td><td>Vàng, lúa mì, lúa mạch</td></tr><tr><td>Màu / vị</td><td>Vàng / đắng</td></tr><tr><td>Ngày</td><td>Chủ nhật</td></tr></tbody></table><h3 id="than-thoai-va-ten-goi-sach" tabindex="-1">Thần thoại và tên gọi [Sách] <a class="header-anchor" href="#than-thoai-va-ten-goi-sach" aria-label="Permalink to &quot;Thần thoại và tên gọi [Sách]&quot;">​</a></h3><ul><li>Tên thơ ca: <em>Phōs</em> (= ánh sáng)</li><li>Shamesh (Babylon), Hēlios, Apollō (Hy Lạp): đều có tia sáng tỏa từ đầu, gắn với <strong>bói toán</strong> và <strong>lời thề</strong></li></ul><h3 id="cot-loi-sach" tabindex="-1">Cốt lõi [Sách] <a class="header-anchor" href="#cot-loi-sach" aria-label="Permalink to &quot;Cốt lõi [Sách]&quot;">​</a></h3><ul><li>Bản chất (Valens): <strong>To build</strong>, essence: <strong>ruler of light</strong></li><li>Archetype hiện đại: <strong>The Leader / The Illuminator</strong></li></ul><p><strong>Cách nhớ:</strong> Sun giống &quot;ngọn đèn giữa phòng&quot;. Mọi thứ trong phòng chỉ được nhìn thấy nhờ đèn, nên Sun liên quan tới <em>được nhìn thấy, được công nhận, có mục đích sống</em>.</p><hr><h2 id="_3-essential-dignity-cua-sun-bo-sung" tabindex="-1">3. Essential dignity của Sun [Bổ sung] <a class="header-anchor" href="#_3-essential-dignity-cua-sun-bo-sung" aria-label="Permalink to &quot;3. Essential dignity của Sun [Bổ sung]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Loại</th><th>Vị trí</th><th>Ý nghĩa dễ hiểu</th></tr></thead><tbody><tr><td>Domicile (nhà riêng)</td><td><strong>Leo</strong></td><td>Ở nhà mình, thoải mái nhất</td></tr><tr><td>Exaltation (khách quý)</td><td><strong>Aries</strong> (nổi tiếng là khoảng 19°)</td><td>Được tôn vinh, đầy năng lượng</td></tr><tr><td>Triplicity</td><td>Nhóm <strong>lửa</strong> (Aries, Leo, Sagittarius), Sun cai quản <strong>ban ngày</strong></td><td>Có chỗ dựa vào ban ngày</td></tr><tr><td>Detriment (nhà kẻ thù)</td><td><strong>Aquarius</strong></td><td>Đối diện nhà mình, mất quyền lực</td></tr><tr><td>Fall</td><td><strong>Libra</strong></td><td>Đối diện nơi được tôn vinh, &quot;ngã&quot;</td></tr></tbody></table><p>Lưu ý: Leo là nhà của Sun, Cancer là nhà của Moon. Hai nhà này nằm cạnh nhau, là &quot;điểm khởi đầu&quot; của vòng rulership mà bạn thấy ở Figure 3 (liên quan đến <em>thema mundi</em> sẽ học sau).</p><hr><h2 id="_4-sect-joy-va-solar-phase-cua-sun-bo-sung" tabindex="-1">4. Sect, Joy và Solar phase của Sun [Bổ sung] <a class="header-anchor" href="#_4-sect-joy-va-solar-phase-cua-sun-bo-sung" aria-label="Permalink to &quot;4. Sect, Joy và Solar phase của Sun [Bổ sung]&quot;">​</a></h2><ul><li><strong>Sect:</strong> Sun là ánh sáng của <strong>phe ngày</strong> (diurnal). Lá số ban ngày, Sun &quot;đang ở sân nhà&quot; về mặt sect</li><li><strong>Joy (nơi vui thích):</strong> <strong>House 9</strong> (tôn giáo, triết học, ý nghĩa cuộc đời). Khá hợp với Sun là &quot;nguồn sáng của ý nghĩa&quot;</li><li><strong>Combust / cazimi</strong> (chỉ áp dụng cho hành tinh <em>khác</em> so với Sun, nhưng bạn cần hiểu vì nó là cơ chế của Sun): <ul><li><strong>Cazimi</strong>: hành tinh nằm <strong>cực sát Sun</strong> (khoảng vài phút cung), được coi là &quot;ngồi trên ngai của vua&quot;, <strong>rất mạnh</strong></li><li><strong>Combust</strong>: hành tinh sát Sun trong khoảng vài độ (thường ghi khoảng 8 đến 8.5 độ), bị &quot;cháy&quot;, yếu đi nặng</li><li><strong>Under the beams</strong>: xa hơn chút (khoảng 15 độ), bị lu mờ vì ánh sáng Sun</li><li>Con số cụ thể khác nhau giữa các tác giả, hãy dùng đúng số trong chương solar phase của sách</li></ul></li></ul><p><strong>Ví dụ dễ hình dung:</strong> đứng cách bóng đèn pha 1 mét thì bạn bị chói mắt đến nỗi không nhìn thấy gì (combust). Đứng ngay trước mặt đèn lại nằm trong vùng sáng nhất, thành tâm điểm (cazimi). Đứng xa vừa phải thì thấy rõ (oriental/occidental, free of the beams).</p><hr><h2 id="_5-sun-tot-vs-xau-đoc-nhu-the-nao" tabindex="-1">5. Sun tốt vs xấu: đọc như thế nào <a class="header-anchor" href="#_5-sun-tot-vs-xau-đoc-nhu-the-nao" aria-label="Permalink to &quot;5. Sun tốt vs xấu: đọc như thế nào&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition tốt</th><th>Condition xấu</th></tr></thead><tbody><tr><td>Ở Leo/Aries, hoặc có dignity khác; ở nhà góc hoặc house 9, 10, 11; lá số ngày; nhận trine/sextile từ Jupiter/Venus</td><td>Ở Aquarius/Libra; ở house 6, 8, 12; bị Saturn/Mars chiếu căng; lá số đêm mà không có hỗ trợ khác</td></tr><tr><td>Thường biểu hiện: có mục đích rõ ràng, được công nhận, sức sống tốt, quan hệ với cha/người quyền lực thuận lợi</td><td>Thường biểu hiện: thiếu tự tin, khó được ghi nhận, sức sống thấp, quan hệ khó khăn với cha/người quyền lực</td></tr></tbody></table><p><strong>Insight:</strong> Sun ở house nào cho biết <em>chủ đề nào của đời sống là nơi người đó muốn tỏa sáng</em>. Condition của Sun cho biết <em>họ có đủ sức tỏa sáng ở đó không</em>. (Đúng nguyên tắc Morin: house chỉ cho chủ đề, condition quyết định tốt hay xấu.)</p><hr><h2 id="_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">6. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;6. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><h3 id="checklist-đanh-gia-sun-lam-theo-thu-tu" tabindex="-1">Checklist đánh giá Sun (làm theo thứ tự) <a class="header-anchor" href="#checklist-đanh-gia-sun-lam-theo-thu-tu" aria-label="Permalink to &quot;Checklist đánh giá Sun (làm theo thứ tự)&quot;">​</a></h3><ol><li>Lá số ngày hay đêm? (Sun in sect hay không)</li><li>Sun ở sign nào, có dignity gì? (domicile, exaltation, triplicity ban ngày, hay detriment/fall, hay peregrine)</li><li>Sun ở house nào, nhà đó mạnh hay yếu? Có phải house 9 (joy)?</li><li>Sun nhận aspect từ ai? Có benefic hỗ trợ không, có malefic gây áp lực không?</li><li>Sun cai quản house nào (theo sign Leo nằm ở house mấy)? Condition của Sun ảnh hưởng chủ đề house đó</li></ol><h3 id="sun-noi-đuoc-gi-ve-nguoi-đo" tabindex="-1">Sun nói được gì về người đó <a class="header-anchor" href="#sun-noi-đuoc-gi-ve-nguoi-đo" aria-label="Permalink to &quot;Sun nói được gì về người đó&quot;">​</a></h3><ul><li><strong>Mục đích sống, bản sắc, cách họ muốn được nhìn nhận</strong></li><li><strong>Sức sống tổng thể</strong> (sách coi Sun liên quan &quot;life breath&quot;)</li><li><strong>Cha, người có quyền lực, sếp, người bảo trợ</strong> (đặc biệt trong lá số ngày)</li><li><strong>Danh tiếng, vinh dự</strong></li></ul><h3 id="cach-noi-voi-nguoi-đoi-dien-vi-du" tabindex="-1">Cách nói với người đối diện (ví dụ) <a class="header-anchor" href="#cach-noi-voi-nguoi-đoi-dien-vi-du" aria-label="Permalink to &quot;Cách nói với người đối diện (ví dụ)&quot;">​</a></h3><ul><li>Sun mạnh: &quot;Bạn có xu hướng tự nhiên làm người dẫn dắt hoặc được người khác nhìn vào. Bạn không cần ép mình, chỉ cần nhớ dùng nó có trách nhiệm.&quot;</li><li>Sun yếu: &quot;Cảm giác &#39;mình đang ở đâu trong bức tranh lớn&#39; có thể mờ hơn. Điều này không có nghĩa bạn kém, chỉ là bạn cần xây sự tự tin bằng hành động cụ thể hơn là chờ được công nhận.&quot;</li></ul><h3 id="luu-y" tabindex="-1">Lưu ý <a class="header-anchor" href="#luu-y" aria-label="Permalink to &quot;Lưu ý&quot;">​</a></h3><ul><li>Đừng nói &quot;Sun yếu nên bạn sẽ thất bại&quot;. Theo đúng tinh thần note_5: lá số mô tả <strong>hoàn cảnh/tiền đề</strong>, không ép buộc hành động</li><li>Nếu khách hỏi về cha: hỏi họ trước về mối quan hệ thực tế, đừng áp ngay &quot;Sun yếu = cha có vấn đề&quot;</li><li>Không dùng Sun để chẩn đoán bệnh tim hay mắt. Đây là ý nghĩa <strong>tượng trưng truyền thống</strong>, không phải y khoa</li></ul><hr><h2 id="_7-loi-thuong-gap" tabindex="-1">7. Lỗi thường gặp <a class="header-anchor" href="#_7-loi-thuong-gap" aria-label="Permalink to &quot;7. Lỗi thường gặp&quot;">​</a></h2><ul><li>Quên rằng Sun là <strong>trung tính</strong> (không phải benefic hay malefic). Nhưng Sun có thể &quot;đốt&quot; các hành tinh khác nếu quá gần</li><li>Đọc Sun chỉ như &quot;cái tôi&quot; kiểu hiện đại. Truyền thống rộng hơn nhiều: cha, quyền lực, danh tiếng, sức sống, linh hồn</li><li>Dùng sign hiện đại để đoán dignity (Sun chỉ có domicile ở <strong>Leo</strong>, không có sign nào khác)</li></ul>',43)])])}const m=t(a,[["render",g]]);export{d as __pageData,m as default};
